async function hashPassword(password) {
    const salt = crypto.randomBytes(SALT_BYTES);
    const derived = await scrypt(password, salt, KEY_LENGTH);
    return `${salt.toString('hex')}:${derived.toString('hex')}`;
}

module.exports = { hashPassword };

