// Usage: node probe.js <baseUrl> [adminToken]
const base = process.argv[2];
const token = process.argv[3];
const adminHeaders = token ? { 'X-Admin-Token': token } : {};

const cases = [
  ['checkout success', 'POST', '/api/checkout', { usr: 'Guilherme', eml: 'gui@fullcycle.com.br', pwd: 'senhaforte', c_id: 2, card: '4111222233334444' }],
  ['checkout existing user', 'POST', '/api/checkout', { usr: 'Leonan', eml: 'leonan@fullcycle.com.br', pwd: '123', c_id: 2, card: '4111222233334444' }],
  ['checkout denied', 'POST', '/api/checkout', { usr: 'João', eml: 'joao@teste.com', pwd: '123', c_id: 1, card: '5111222233334444' }],
  ['checkout missing field', 'POST', '/api/checkout', { usr: 'X' }],
  ['checkout unknown course', 'POST', '/api/checkout', { usr: 'X', eml: 'x@x.com', pwd: 'abcdef', c_id: 999, card: '4111' }],
  ['report', 'GET', '/api/admin/financial-report', null, adminHeaders],
  ['report no token', 'GET', '/api/admin/financial-report', null, {}],
  ['delete user 1', 'DELETE', '/api/users/1', null, adminHeaders],
  ['report after delete', 'GET', '/api/admin/financial-report', null, adminHeaders],
  ['delete no token', 'DELETE', '/api/users/2', null, {}],
  ['unknown route', 'GET', '/api/nope', null, {}],
  ['checkout numeric card', 'POST', '/api/checkout', { usr: 'Y', eml: 'y@y.com', pwd: 'abcdef', c_id: 1, card: 4111 }],
  ['after numeric card', 'GET', '/api/nope', null, {}],
];

(async () => {
  for (const [name, method, path, body, extra = {}] of cases) {
    try {
      const res = await fetch(base + path, {
        method,
        headers: { ...(body ? { 'Content-Type': 'application/json' } : {}), ...extra },
        body: body ? JSON.stringify(body) : undefined,
      });
      const ct = res.headers.get('content-type') || '';
      const text = await res.text();
      let shape = ct.split(';')[0];
      let preview = text.slice(0, 160);
      if (ct.includes('json')) {
        const data = JSON.parse(text);
        shape = Array.isArray(data) ? `array[${data.length}] keys=${data[0] ? Object.keys(data[0]).join(',') : ''}` : `keys=${Object.keys(data).join(',')}`;
        preview = text.slice(0, 220);
      }
      console.log(`${name.padEnd(24)} ${method.padEnd(6)} ${path.padEnd(30)} ${res.status} ${shape} | ${preview}`);
    } catch (err) {
      console.log(`${name.padEnd(24)} ${method.padEnd(6)} ${path.padEnd(30)} ERROR ${err.message}`);
    }
  }
})();

